import * as React from "react";
import {SvgMpaLogo} from "../../assets/icons/index";

export interface LogoComponentProps {    
 /**
 * determines the name of Logo
 */
    logoName: keyof typeof SvgMpaLogo | string;
    /**
 * determines the width of logo
 */
    width?: string | number;
    /**
 * determines the width of logo
 */
    height?: number | string;
}

export const MpaLogo: React.FC<LogoComponentProps> = ({logoName, width, height}) => {
    
    const LogoComponent = SvgMpaLogo[logoName as keyof typeof SvgMpaLogo];
    // const LogoComponent = SvgMpaLogo[logoName];
    if (!LogoComponent) {
        console.warn(`MpaLogo: logo "${logoName}" not found in SvgMpaLogo`);
        return null;
    }
    return (
        <LogoComponent width={width} height={height}/>    
    )
}

export default MpaLogo;